option.value:
.home { padding-bottom: calc(32px + var(--safe-bottom)); }
.hero {
  position: relative;
  height: 280px;
  background: url('https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=1200&q=80') center/cover no-repeat;
  display: flex;
  align-items: flex-end;
  overflow: hidden;

  @media (min-width: 768px) { height: 380px; }

  &__overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(to top, rgba(13,18,87,0.92) 0%, rgba(13,18,87,0.4) 60%, transparent 100%);
  }

  &__content {
    position: relative;
    z-index: 1;
    padding-bottom: 32px;
    color: #fff;

    h1 {
      margin: 0 0 8px;
      font-size: clamp(28px, 6vw, 48px);
      font-weight: 800;
      letter-spacing: -1px;
      span { color: var(--accent-light); }
    }

    p {
      margin: 0 0 20px;
      font-size: clamp(14px, 3vw, 18px);
      opacity: 0.9;
      max-width: 500px;
    }
  }
}

.modules {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 16px;
  padding-top: 24px;
  padding-bottom: 8px;
}

.module-card {
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow-card);
  display: block;
  cursor: pointer;
  transition: transform 0.2s, box-shadow 0.2s;
  text-decoration: none;

  &:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 32px rgba(26,35,126,0.18);
  }

  &:active { transform: scale(0.98); }

  &__img {
    position: relative;
    height: 180px;
    background: #1a237e;
    overflow: hidden;

    img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 0.4s;
    }

    &:hover img { transform: scale(1.05); }

    &-overlay {
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(26,35,126,0.5) 0%, transparent 60%);
    }
  }

  &__label {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 16px;
    background: #fff;
    font-size: 18px;
    font-weight: 700;
    color: var(--text-primary);

    .material-icons { color: var(--primary); font-size: 22px; }
  }

  &--accent .module-card__label {
    background: var(--accent);
    color: #fff;
    .material-icons { color: #fff; }
  }

  &--setup {
    border: 1px solid var(--border);
    box-shadow: none;
  }

  &__label--stack {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
    font-size: 14px;
    font-weight: 500;

    p { margin: 0; color: var(--text-secondary); line-height: 1.4; }

    input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 10px 12px;
      font-size: 14px;
    }
  }
}

.setup-inline {
  display: grid;
  gap: 8px;
  grid-template-columns: 1fr auto;

  .btn {
    width: 100%;
    margin: 0;
    justify-content: center;
  }
}

.create-placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, var(--accent) 0%, #e65100 100%);
  height: 180px;
  .material-icons { font-size: 72px; color: rgba(255,255,255,0.6); }
}

.about-section { padding-top: 24px; }

.about-card {
  padding: 24px 20px;

  &__icon {
    font-size: 36px;
    margin-bottom: 12px;
  }

  h2 {
    margin: 0 0 14px;
    font-size: 20px;
    font-weight: 800;
    color: var(--text-primary);
  }

  p {
    margin: 0 0 12px;
    font-size: 14px;
    color: var(--text-secondary);
    line-height: 1.7;
  }

  &__call {
    font-weight: 700;
    color: var(--primary);
    font-size: 14px;
    margin-bottom: 0 !important;
  }
}

.org-section { padding-top: 32px; }

.section-title {
  font-size: 20px;
  font-weight: 700;
  margin: 0 0 16px;
  color: var(--text-primary);
}

.org-card {
  padding: 20px;

  &__header {
    display: flex;
    gap: 16px;
    align-items: flex-start;
    margin-bottom: 12px;

    h3 {
      margin: 0 0 4px;
      font-size: 17px;
      font-weight: 700;
      color: var(--text-primary);
      line-height: 1.3;
    }
  }
}

.org-logo {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  object-fit: cover;
  border: 3px solid var(--border);
  flex-shrink: 0;
}

.org-location {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 13px;
  color: var(--text-secondary);
  margin: 0;
  .material-icons { font-size: 14px; }
}

.org-desc {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.5;
  margin: 0 0 16px;
}

.cta-section { padding-top: 32px; }

.cta-card {
  padding: 28px 20px;
  text-align: center;

  h3 { margin: 0 0 8px; font-size: 20px; }
  p  { margin: 0 0 20px; font-size: 14px; color: var(--text-secondary); line-height: 1.5; }
}

.cta-icon {
  display: block;
  font-size: 52px;
  color: var(--primary-light);
  margin-bottom: 12px;
}

.home { padding-bottom: calc(32px + var(--safe-bottom)); }
