  }
}

.group-placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 180px;
  background: linear-gradient(135deg, var(--primary) 0%, #3949ab 100%);
  .material-icons { font-size: 72px; color: rgba(255,255,255,0.55); }
}

.setup-chevron {
  font-size: 20px !important;
  margin-left: auto;
  color: var(--text-secondary) !important;
  transition: transform 0.2s;

  &--open { transform: rotate(180deg); }
}

.setup-section { padding: 16px 0 0; }

.setup-card {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  padding: 24px 20px;

  &__col {
    flex: 1 1 240px;
    display: flex;
    flex-direction: column;
    gap: 10px;

    h4 {
      display: flex;
      align-items: center;
      gap: 6px;
      margin: 0;
      font-size: 16px;
      font-weight: 700;
      color: var(--text-primary);
      .material-icons { font-size: 18px; color: var(--primary); }
    }

    p { margin: 0; font-size: 13px; color: var(--text-secondary); }

    input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 10px 12px;
      font-size: 14px;
      box-sizing: border-box;
    }
  }

  &__divider {
    width: 1px;
    background: var(--border);
    @media (max-width: 540px) { width: 100%; height: 1px; }
  }

  &__feedback {
    width: 100%;
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 13px;
    font-weight: 600;
    margin: 0;

    &--error { color: #b71c1c; .material-icons { font-size: 16px; } }
  }
}

.setup-inline {
  display: grid;
  gap: 8px;
  grid-template-columns: 1fr auto;

  .btn { margin: 0; }

  &--triple { grid-template-columns: minmax(80px,1fr) 70px auto; }
}

