import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { OrganizationService } from '../../services/organization.service';
import { Organization } from '../../models/organization.model';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [CommonModule, RouterLink, FormsModule],
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})
export class HomeComponent implements OnInit {
  organizations: Organization[] = [];
  userOrg: Organization | undefined;
  joinCode = '';
  newOrgName = '';
  newOrgCity = '';
  newOrgState = '';
  newOrgDescription = '';
  orgSetupError = '';
  orgSetupSuccess = '';

  constructor(
    public auth: AuthService,
    private orgService: OrganizationService
  ) {}

  ngOnInit(): void {
    this.refreshOrganizations();
  }

  joinOrganization(): void {
    this.orgSetupError = '';
    this.orgSetupSuccess = '';

    const result = this.auth.joinOrganization(this.joinCode);
    if (!result.success) {
      this.orgSetupError = result.message;
      return;
    }

    this.joinCode = '';
    this.orgSetupSuccess = result.message;
    this.refreshOrganizations();
  }

  createOrganization(): void {
    this.orgSetupError = '';
    this.orgSetupSuccess = '';

    const createResult = this.orgService.createOrganization({
      name: this.newOrgName,
      city: this.newOrgCity,
      state: this.newOrgState,
      description: this.newOrgDescription
    });

    if (!createResult.success || !createResult.organization) {
      this.orgSetupError = createResult.message;
      return;
    }

    const assignResult = this.auth.assignCurrentUserToOrganization(createResult.organization.id, 'ADMIN');
    if (!assignResult.success) {
      this.orgSetupError = assignResult.message;
      return;
    }

    this.newOrgName = '';
    this.newOrgCity = '';
    this.newOrgState = '';
    this.newOrgDescription = '';
    this.orgSetupSuccess = `Organizacao ${createResult.organization.name} criada! Seu codigo: ${createResult.organization.joinCode}.`;
    this.refreshOrganizations();
  }

  private refreshOrganizations(): void {
    this.orgService.getOrganizations().subscribe(orgs => {
      this.organizations = orgs;
      const orgId = this.auth.getUserOrganizationId();
      this.userOrg = orgId ? orgs.find(o => o.id === orgId) : undefined;
    });
  }
}

import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { OrganizationService } from '../../services/organization.service';
import { Organization } from '../../models/organization.model';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [CommonModule, RouterLink, FormsModule],
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})
export class HomeComponent implements OnInit {
  organizations: Organization[] = [];
  userOrg: Organization | undefined;
  showSetupPanel = false;
  joinCode = '';
  newOrgName = '';
  newOrgCity = '';
  newOrgState = '';
  newOrgDescription = '';
  orgSetupError = '';
  orgSetupSuccess = '';

  constructor(
    public auth: AuthService,
    private orgService: OrganizationService
  ) {}

  ngOnInit(): void {
    this.refreshOrganizations();
  }

  joinOrganization(): void {
    this.orgSetupError = '';
    this.orgSetupSuccess = '';

    const result = this.auth.joinOrganization(this.joinCode);
    if (!result.success) {
      this.orgSetupError = result.message;
      return;
    }

    this.joinCode = '';
    this.orgSetupSuccess = result.message;
    this.showSetupPanel = false;
    this.refreshOrganizations();
  }

  createOrganization(): void {
    this.orgSetupError = '';
    this.orgSetupSuccess = '';

    const createResult = this.orgService.createOrganization({
      name: this.newOrgName,
      city: this.newOrgCity,
      state: this.newOrgState,
      description: this.newOrgDescription
    });

    if (!createResult.success || !createResult.organization) {
      this.orgSetupError = createResult.message;
      return;
    }

    const assignResult = this.auth.assignCurrentUserToOrganization(createResult.organization.id, 'ADMIN');
    if (!assignResult.success) {
      this.orgSetupError = assignResult.message;
      return;
    }

    this.newOrgName = '';
    this.newOrgCity = '';
    this.newOrgState = '';
    this.newOrgDescription = '';
    this.orgSetupSuccess = `Organizacao ${createResult.organization.name} criada! Seu codigo: ${createResult.organization.joinCode}.`;
    this.showSetupPanel = false;
    this.refreshOrganizations();
  }

  private refreshOrganizations(): void {
    this.orgService.getOrganizations().subscribe(orgs => {
      this.organizations = orgs;
      const orgId = this.auth.getUserOrganizationId();
      this.userOrg = orgId ? orgs.find(o => o.id === orgId) : undefined;
    });
  }
}
